# GENERATED from the game files by du_points_extract.py + du_mapdata_gen.py --
# do not edit by hand.
#
# SAGA_POINTS[du character id][saga block 0-3] = {
#     "marker":  (event, x, z) or None   event that ends the saga, and a free spot for it
#     "openers": {chapter: event}        scene that opens each chapter after the first
#     "points":  [MapPoint, ...]         in the order the game's own scripts reach them
# }
# An event code is (class << 16) | id. See MapPoint below for the fields.
from collections import namedtuple

MapPoint = namedtuple("MapPoint", (
    "code",          # event the point starts
    "flags",         # as the game places it
    "type",          # location type (picks the name shown)
    "radius",        # how close the player has to be
    "x", "y", "z",
    "level_min",     # level range the point is limited to; -1 = no limit
    "level_max",
    "chapter",       # story fights that come before the game places the point
    "fight",         # starts a battle itself
    "next",          # for a fight: the scene it queues for after the battle
    "starts_fight",  # a talk scene that runs straight into a fight
    "fight_key",     # same for every point that leads to one fight (its `next`)
))
